import {displayProject,collectLegacyNotes,layoutKey,updateHuman,editCuts,emptyLearning,validateLearning,newMethod,methodContext} from './study-tools.mjs';
const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!=null)n.textContent=text;if(cls)n.className=cls;return n;};
const button=(label,fn,cls='')=>{const b=node('button',label,cls);b.type='button';b.onclick=()=>Promise.resolve(fn()).catch(e=>alert(e.message));return b;};
const now=()=>new Date().toISOString();
export function installWorkbench(api){
 const {$}=api;let cached=null,libraryDB=null,learningSave=Promise.resolve(),mutation=Promise.resolve(),undo=null;
 async function localLibrary(){return libraryDB??=new Promise((resolve,reject)=>{const r=indexedDB.open('guanlan-learning-library',1);r.onupgradeneeded=()=>r.result.createObjectStore('library');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
 async function learning(refresh=false){if(cached&&!refresh)return cached;if(api.desktop()){cached=await api.request('/api/learning');}else{const db=await localLibrary();cached=await new Promise((resolve,reject)=>{const tx=db.transaction('library'),r=tx.objectStore('library').get('main');r.onsuccess=()=>resolve(r.result||emptyLearning());r.onerror=()=>reject(r.error);});}const projects=await api.all();for(const m of cached.methods){const source=projects.find(p=>p.id===m.projectId);if(source&&m.sourceLayout!==layoutKey(source)){m.reviewed=false;m.reviewedAt=null;m.sourceChanged=true;}}return cached;}
 function saveLearning(input){const value=validateLearning(input);value.updated=now();const save=async()=>{if(api.desktop())await api.request('/api/learning',value);else{const db=await localLibrary();await new Promise((resolve,reject)=>{const tx=db.transaction('library','readwrite');tx.objectStore('library').put(value,'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}cached=value;};learningSave=learningSave.catch(()=>{}).then(save);return learningSave;}
 function modal(title){const dialog=node('dialog',null,'learning-dialog'),head=node('div',null,'learning-heading');head.append(node('h2',title),button('关闭 ×',()=>{dialog.close();dialog.remove();},'quiet'));dialog.append(head);document.body.append(dialog);dialog.addEventListener('cancel',()=>dialog.remove());dialog.showModal();return dialog;}
 function field(parent,label,value='',rows=3){const wrap=node('label',label),input=node(rows===1?'input':'textarea');if(rows!==1)input.rows=rows;input.value=value;wrap.append(input);parent.append(wrap);return input;}
 function download(name,data){api.download(name,new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));}
 function alive(p,key){if(!api.getActive()||api.getActive().id!==p.id||layoutKey(api.getActive())!==key)throw Error('项目或镜头已变更，请重新操作');}
 async function saveProject(p){p.updated=now();await api.save(p);api.setActive(p);await api.library();api.showPrepared();}
 async function getProject(){let p=api.getActive();if(!p)throw Error('请先打开一份拉片');if(api.desktop())p=await api.request('/api/project?id='+encodeURIComponent(p.id));if(api.desktop())p._expectedUpdated=p.updated;return collectLegacyNotes(p,localStorage);}
 async function capture(p,ids,src){if(!src)throw Error('请先在报告播放器选择对应原片，再调整镜头');const v=document.createElement('video');v.muted=true;v.preload='auto';v.src=src;const wait=(event,trigger)=>new Promise((resolve,reject)=>{const cleanup=()=>{clearTimeout(timer);v.removeEventListener(event,ok);v.removeEventListener('error',bad);},ok=()=>{cleanup();resolve();},bad=()=>{cleanup();reject(Error('无法解码对应原片'));},timer=setTimeout(()=>{cleanup();reject(Error('视频定位超时，请重新选择原片'));},20000);v.addEventListener(event,ok,{once:true});v.addEventListener('error',bad,{once:true});trigger();});try{await wait('loadeddata',()=>v.load());if(Math.abs(v.duration-p.meta.sourceDuration)>.5)throw Error('当前视频时长不匹配，请选择对应原片');const canvas=document.createElement('canvas');canvas.height=576;canvas.width=Math.round(576*v.videoWidth/v.videoHeight);const ctx=canvas.getContext('2d');for(const s of p.shots.filter(s=>ids.includes(s.id))){s.images=[];s.frames=[];s.sampleTimes=[];for(const f of [.15,.5,.85]){const t=p.meta.sourceStart+s.start+s.duration*f;if(Math.abs(v.currentTime-t)>.001)await wait('seeked',()=>v.currentTime=t);ctx.drawImage(v,0,0,canvas.width,canvas.height);s.images.push(canvas.toDataURL('image/jpeg',.8));s.frames.push(t);s.sampleTimes.push(t);}}}finally{v.pause();v.removeAttribute('src');v.load();}}
 function answer(data,ok,error){$('viewer').contentWindow?.postMessage({type:'guanlan-response',requestId:data.requestId,ok,error},location.origin);}
 window.addEventListener('message',e=>{if(e.source!==$('viewer').contentWindow||e.origin!==location.origin||!e.data||e.data.type!=='guanlan-action')return;const data=e.data;if(!['save-human','cut','save-method'].includes(data.action))return;mutation=mutation.catch(()=>{}).then(async()=>{if(api.busy())throw Error('当前正在处理素材，请完成后再修改');let p=await getProject();alive(p,data.layout);if(p.id!==data.projectId)throw Error('项目已切换');if(data.action==='save-human'){p=updateHuman(p,data.shotId,data.human,data.reviews);await saveProject(p);undo=null;$('undo-cut').hidden=true;answer(data,displayProject(p));return;}
 if(data.action==='save-method'){const s=p.shots.find(s=>s.id===data.shotId);if(!s)throw Error('镜头不存在');const lib=await learning(true),card=newMethod(p,s,data.method);lib.methods.unshift(card);await saveLearning(lib);answer(data,{message:card.reviewed?'方法已保存到学习库，可明确选用于其他项目':'方法草稿已保存，复核后才能用于项目'});return;}
 const source=$('viewer').contentDocument?.querySelector('video')?.getAttribute('src'),before=structuredClone(p);const result=editCuts(p,{type:data.cutType,shotId:data.shotId,time:data.time});api.setBusy(true);try{api.status('正在重抽受影响镜头，其他镜头与人工记录保留…');await capture(result.project,result.affected,source);alive(p,data.layout);api.backup(before);await saveProject(result.project);const lib=await learning(true);let invalidated=false;for(const m of lib.methods)if(m.projectId===p.id&&m.reviewed&&m.sourceLayout!==layoutKey(result.project)){m.reviewed=false;m.reviewedAt=null;m.sourceChanged=true;invalidated=true;}if(invalidated)await saveLearning(lib);undo={projectId:p.id,before,after:result.project.updated};$('undo-cut').hidden=false;await api.openReport(false,{time:data.time??result.project.shots.find(s=>s.id===result.selected).start});api.status('镜头已局部调整；受影响的旧记录存入项目历史，并已下载调整前备份。');}finally{api.setBusy(false);}}).catch(err=>{answer(data,null,err.message);api.status(err.message,true);});});
 async function editMethod(m){const d=modal('编辑导演方法'),title=field(d,'方法名称',m.title,1),method=field(d,'具体做法',m.method),when=field(d,'适用条件',m.when),limits=field(d,'不适用情况与边界',m.limits),tags=field(d,'标签',m.tags,1),label=node('label',null,'check'),check=node('input');check.type='checkbox';check.checked=m.reviewed;label.append(check,node('span','我已回看来源，并核对方法与适用边界'));d.append(label,button('保存方法',async()=>{const lib=await learning(true),target=lib.methods.find(x=>x.id===m.id);if(!target)throw Error('方法已不存在');Object.assign(target,{title:title.value.trim(),method:method.value.trim(),when:when.value.trim(),limits:limits.value.trim(),tags:tags.value.trim(),reviewed:check.checked,reviewedAt:check.checked?now():null});await saveLearning(lib);d.close();d.remove();document.querySelector('#learning-library')?.close();document.querySelector('#learning-library')?.remove();await showLibrary('methods');},'primary'));}
 async function showLibrary(tab='methods'){const d=modal('我的学习库');d.id='learning-library';const tabs=node('div',null,'actions'),search=node('input');search.placeholder='搜索名称、标签、方法或资料文字';search.setAttribute('aria-label','搜索学习库');const body=node('div',null,'learning-items'),tools=node('div',null,'actions');for(const [id,label] of [['methods','导演方法'],['resources','参考资料']])tabs.append(button(label,()=>{tab=id;render();},tab===id?'active':''));d.append(tabs,search,tools,body);let lib=await learning(true);
 async function render(){body.replaceChildren();tools.replaceChildren();tools.append(button('备份学习库',()=>download('观澜学习库.json',lib)));if(lib.trash?.length)tools.append(button('撤销最近移除',async()=>{const current=await learning(true),item=current.trash.pop();if(item&&!current[item.kind].some(x=>x.id===item.value.id))current[item.kind].unshift(item.value);await saveLearning(current);lib=current;render();}));const restore=node('input');restore.type='file';restore.accept='.json';restore.hidden=true;restore.onchange=async()=>{try{const f=restore.files[0];if(!f||f.size>28e6)throw Error('备份文件过大或无效');const incoming=validateLearning(JSON.parse(await f.text())),current=await learning(true);for(const k of ['methods','resources'])for(const item of incoming[k])if(!current[k].some(x=>x.id===item.id))current[k].push(item);await saveLearning(current);lib=current;await render();}catch(e){alert(e.message);}finally{restore.value='';}};tools.append(restore,button('恢复备份',()=>restore.click()));if(tab==='resources')tools.append(button('添加参考资料',()=>addResource()));const query=search.value.trim().toLowerCase(),items=lib[tab].filter(x=>JSON.stringify([x.title,x.tags,x.method,x.text]).toLowerCase().includes(query));for(const x of items){const card=node('article',null,'learning-card');card.append(node('h3',x.title),node('p',x.tags||'未分类','small muted'));if(tab==='methods'){card.append(node('p',x.method),node('p','适用：'+x.when),node('p','边界：'+x.limits,'small muted'),node('p',`${x.projectTitle} · ${x.start.toFixed(2)}—${x.end.toFixed(2)} 秒 · ${x.reviewed?'已人工复核':'草稿，待复核'}`,'small muted'));const actions=node('div',null,'actions');actions.append(button('查看来源',async()=>{const p=(await api.all()).find(p=>p.id===x.projectId);if(!p)throw Error('来源项目不在当前设备，请先恢复该项目备份');d.close();d.remove();api.setActive(p);api.showPrepared();await api.openReport(false,{time:x.start});if(layoutKey(p)!==x.sourceLayout)api.status('来源镜头已经调整，已定位原时间；方法证据请重新核对。',true);}),button('编辑与复核',()=>editMethod(x)));const p=api.getActive();if(p){const selected=p.methodIds?.includes(x.id);actions.append(button(selected?'从当前项目移除':'用于当前项目',async()=>{if(!x.reviewed&&!selected)throw Error('请先编辑并人工复核这条方法');const current=await getProject();current.methodIds=selected?(current.methodIds||[]).filter(id=>id!==x.id):[...new Set([...(current.methodIds||[]),x.id])];await saveProject(current);api.status(selected?'已移除学习参考':'方法已明确选入当前项目；下次分析会作为参考，不能替代影片证据。');render();}));}card.append(actions);}else{card.append(node('p',x.kind||'文档','small muted'));const pre=node('pre',x.text||'附件参考');card.append(pre);if(x.dataUrl){if(x.dataUrl.startsWith('data:image/')){const img=node('img');img.src=x.dataUrl;img.alt=x.title;card.append(img);}else card.append(button('打开 PDF 附件',()=>{const bytes=Uint8Array.from(atob(x.dataUrl.split(',')[1]),c=>c.charCodeAt(0));api.download(x.title.endsWith('.pdf')?x.title:x.title+'.pdf',new Blob([bytes],{type:'application/pdf'}));}));}if(x.projectId)card.append(node('p','关联项目：'+x.projectTitle,'small muted'));const actions=node('div',null,'actions');actions.append(button('修改资料',()=>addResource(x)));if(x.projectId)actions.append(button('打开关联拉片',async()=>{const p=(await api.all()).find(p=>p.id===x.projectId);if(!p)throw Error('关联项目不在当前设备');d.close();d.remove();api.setActive(p);await api.openReport();}));card.append(actions);}card.append(button('移除',async()=>{const current=await learning(true),at=current[tab].findIndex(v=>v.id===x.id);if(at<0)return;const [value]=current[tab].splice(at,1);current.trash=[...(current.trash||[]),{kind:tab,value}].slice(-20);await saveLearning(current);lib=current;render();},'quiet'));body.append(card);}if(!items.length)body.append(node('p',tab==='methods'?'还没有方法卡。打开逐镜报告，在“复核与修订”中保存第一条。':'可添加剧本、作者分析、拍剪图、方法图或表格摘要，并关联拉片项目。','muted'));}
 async function addResource(old=null){const edit=modal(old?'修改参考资料':'添加参考资料'),title=field(edit,'资料名称',old?.title||'',1),tags=field(edit,'分类与标签',old?.tags||'',1),kind=node('select');for(const x of ['作者分析','剧本','拍剪图','方法图','表格摘要','其他']){const o=node('option',x);o.value=x;kind.append(o);}kind.value=old?.kind||'作者分析';const kindLabel=node('label','资料类型');kindLabel.append(kind);edit.append(kindLabel);const text=field(edit,'文字内容 / 表格摘要',old?.text||'',6),file=node('input');file.type='file';file.accept='.txt,.md,.srt,.vtt,.png,.jpg,.jpeg,.webp,.pdf';let attachment=old?.dataUrl||'';const fileLabel=node('label','导入文字、图片或 PDF（单附件最多4MB）');fileLabel.append(file);edit.append(fileLabel);file.onchange=async()=>{try{const f=file.files[0];if(!f)return;if(f.size>4e6)throw Error('附件最多4MB，请压缩图片或摘取资料');if(!title.value)title.value=f.name;if(/\.(txt|md|srt|vtt)$/i.test(f.name)){text.value=await f.text();attachment='';}else{attachment=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(f);});}}catch(e){alert(e.message);file.value='';}};const projects=await api.all(),select=node('select');const none=node('option','暂不关联项目');none.value='';select.append(none);for(const p of projects){const o=node('option',p.title);o.value=p.id;select.append(o);}select.value=old?.projectId||api.getActive()?.id||'';const pl=node('label','关联拉片项目');pl.append(select);edit.append(pl,button('保存资料',async()=>{const p=projects.find(p=>p.id===select.value),resource={id:old?.id||crypto.randomUUID(),title:title.value.trim(),tags:tags.value,kind:kind.value,text:text.value,dataUrl:attachment,projectId:p?.id||'',projectTitle:p?.title||'',updated:now()};lib=await learning(true);const index=lib.resources.findIndex(x=>x.id===resource.id);if(index>=0)lib.resources[index]=resource;else lib.resources.unshift(resource);await saveLearning(lib);edit.close();edit.remove();render();},'primary'));}
 search.oninput=()=>render();await render();}
 $('learning-open').onclick=()=>{if(api.busy())return api.status('当前任务完成后可打开学习库。');showLibrary().catch(e=>api.status(e.message,true));};
 $('undo-cut').onclick=async()=>{try{const current=await getProject();if(!undo||current.id!==undo.projectId||current.updated!==undo.after)throw Error('没有可立即撤销的调整，或已有后续修改。可使用调整前项目备份恢复。');api.backup(current);undo.before._expectedUpdated=current.updated;await saveProject(undo.before);undo=null;$('undo-cut').hidden=true;await api.openReport();api.status('已撤销上次局部镜头调整。');}catch(e){api.status(e.message,true);}};
 $('import-link').onclick=async()=>{if(!api.desktop())return api.status('公开链接导入由电脑端提供。请下载并启动 Windows 版；网页版仍可导入本机视频。',true);const value=$('source-link').value.trim();if(!value)return api.status('请先粘贴公开视频链接。',true);const b=$('import-link');b.disabled=true;api.setBusy(true);const abort=new AbortController();$('stop').onclick=()=>abort.abort();try{api.status('正在获取公开视频，下载与解析期间可以停止…');const r=await fetch('/api/import-link',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:value}),signal:abort.signal});const result=await r.json();if(!r.ok)throw Error(result.error||'链接导入失败');const response=await fetch(result.url,{signal:abort.signal});if(!response.ok)throw Error('读取已导入视频失败');await api.loadVideo(new File([await response.blob()],result.name,{type:result.mime}),true);api.setMedia({url:result.url,name:result.name,size:result.size,duration:null});api.status('公开视频已导入。核对画面与时长后准备镜头；来源链接随项目保存。');}catch(e){api.status(e.name==='AbortError'?'已停止链接导入。':e.message,true);}finally{b.disabled=false;api.setBusy(false);api.restoreStop();}};
 return {learning,saveLearning,showLibrary,displayProject,collectLegacyNotes,referenceContext:async p=>methodContext(p,await learning()),restore:async(p,options={})=>{const d=$('viewer').contentDocument;if(!d)return;const v=d.querySelector('video');if(/^\/media\/[a-f0-9-]{36}\.(mp4|webm|mov|m4v)$/.test(p.meta.localMedia?.url||'')&&api.desktop()&&!v?.getAttribute('src')){v.src=p.meta.localMedia.url;v.addEventListener('loadedmetadata',()=>{v.currentTime=p.meta.sourceStart+(options.time||0);},{once:true});}if(options.time!=null){const select=()=>d.defaultView.GuanlanStudy?.seek(p.shots.findIndex(s=>s.start<=options.time&&s.end>options.time));if(v?.readyState>=1)v.currentTime=p.meta.sourceStart+options.time;select();}}};
}
